using System.Net;
using EduConnect.Mvc.Models;
using EduConnect.Mvc.Infrastructure;
using Microsoft.EntityFrameworkCore;
using Xunit;
internal static partial class Cases
{
 static Dictionary<string,string> ProposalForm(Fixture f)=>new(){{"LienHeId",f.Contact.ToString()},{"NhuCauId",f.Need.ToString()},{"TenLop",f.Tag},{"MonHocId",f.M1.ToString()},{"MucTieu","Ôn tập toán"},{"SoBuoiTuan","2"},{"ThoiLuongPhut","60"},{"BatDauHocLuc",DateTime.Today.AddDays(7).ToString("s")},{"HinhThucHoc","TrucTuyen"},{"HocPhi","150000"},{"DonViHocPhi","VND/Gio"},{"LoiNhan","Đề xuất lớp học"},{"LichRanh[0].ThuTrongTuan","1"},{"LichRanh[0].GioBatDau","19:00"},{"LichRanh[0].GioKetThuc","20:00"},{"LichRanh[1].ThuTrongTuan","3"},{"LichRanh[1].GioBatDau","19:00"},{"LichRanh[1].GioKetThuc","20:00"}};
 static async Task<Guid> EndRequest(Fixture f){if(f.Class==Guid.Empty)await f.SeedClass();await using var g=f.Scope(f.G);var q=await g.Connections.TaoYeuCauHuyAsync(f.Class,"Hoàn thành mục tiêu",await f.Version<LopHoc>(f.Class),f.G,default);Assert.True(q.ThanhCong,q.ThongBao);return q.DuLieu;}
 static Task EndExpired(Fixture f,Guid id)=>f.Sql("DECLARE @now datetimeoffset(0)=SYSDATETIMEOFFSET(); UPDATE dbo.YeuCauHuyKetNoi SET GuiLuc=DATEADD(hour,-73,@now),HetHanLuc=DATEADD(hour,-1,@now) WHERE Id=@id",new(){{"@id",id}});
 static async Task NoClass(Fixture f){await using var db=f.Db();Assert.False(await db.Set<LopHoc>().AnyAsync(x=>x.YeuCauKetNoiId==f.Request));Assert.Equal("ChoBenHoc",(await db.Set<YeuCauKetNoiLopHoc>().SingleAsync(x=>x.Id==f.Request)).TrangThai);}
 internal static async Task ConnectionCases(Fixture f,string key){switch(key){
 case "class_rollback":{
  await f.SeedProposal();
  await f.Sql("CREATE OR ALTER TRIGGER dbo.TR_IT_RejectClassSchedule ON dbo.LichHoc AFTER INSERT AS BEGIN THROW 51145,N'Lịch giáo viên bị trùng trong kiểm thử rollback.',1; END");
  try{
   var version=await f.Version<YeuCauKetNoiLopHoc>(f.Request);
   await using(var learner=f.Scope(f.H)){var result=await learner.Connections.ChapNhanDeXuatAsync(f.Request,version,f.H,default);Assert.False(result.ThanhCong);Assert.Equal("409",result.MaLoi);Assert.Contains("trùng",result.ThongDiep!,StringComparison.OrdinalIgnoreCase);}
   await using(var verify=f.Db()){
    Assert.False(await verify.Set<LopHoc>().AnyAsync(x=>x.YeuCauKetNoiId==f.Request));
    Assert.Equal("ChoBenHoc",(await verify.Set<YeuCauKetNoiLopHoc>().SingleAsync(x=>x.Id==f.Request)).TrangThai);
    Assert.Equal("DangMo",(await verify.Set<NhuCauHoc>().SingleAsync(x=>x.Id==f.Need)).TrangThai);
    Assert.False(await verify.Set<CuocHoiThoai>().AnyAsync(x=>x.LienHeId==f.Contact&&x.LoaiHoiThoai=="TheoLop"));
    Assert.False(await verify.Set<ThongBao>().AnyAsync(x=>x.DoiTuongId==f.Request&&x.LoaiThongBao=="KetNoi"));
   }
  }finally{await f.Sql("DROP TRIGGER IF EXISTS dbo.TR_IT_RejectClassSchedule");}
  break;}
 case "proposal_http":{
  foreach(var sender in new[]{"G","H"}){await using var d=new Fixture(f.Id+"-"+sender);await d.Init();await d.SeedNeed();await d.SeedContact();using var c=await d.Client(sender=="G"?d.G:d.H);using var r=await d.Post(c,"/KetNoi/KetNoi/DeXuat",ProposalForm(d));Assert.Equal(HttpStatusCode.OK,r.StatusCode);await using var db=d.Db();var p=await db.Set<YeuCauKetNoiLopHoc>().SingleAsync(x=>x.LienHeId==d.Contact);Assert.Equal(sender=="G"?d.G:d.H,p.NguoiDeXuatId);Assert.Equal(sender=="G"?"ChoBenHoc":"ChoGiaSu",p.TrangThai);Assert.Equal(2,await db.Set<KhungGioDeXuat>().CountAsync(x=>x.YeuCauKetNoiId==p.Id));Assert.Equal(150000,p.HocPhi);Assert.False(await db.Set<LopHoc>().AnyAsync(x=>x.YeuCauKetNoiId==p.Id));}break;}
 case "proposal_edit":{
  for(int dl=0;dl<3;dl++){await using var d=new Fixture(f.Id+"-DL"+dl);await d.Init();await d.SeedProposal();var rv=await d.Version<YeuCauKetNoiLopHoc>(d.Request);if(dl==2)await d.Sql("UPDATE dbo.YeuCauKetNoiLopHoc SET MucTieu=N'Phiên bản mới' WHERE Id=@r",new(){{"@r",d.Request}});using var c=await d.Client(dl==1?d.H:d.G);var form=ProposalForm(d);form["Id"]=d.Request.ToString();form["RowVersion"]=Convert.ToBase64String(rv);form["HocPhi"]="160000";form["LichRanh[0].GioBatDau"]="18:00";form["LichRanh[0].GioKetThuc"]="19:00";using var r=await d.Post(c,"/KetNoi/KetNoi/DeXuat",form);Assert.Equal(dl==0?200:422,(int)r.StatusCode);await using var db=d.Db();var row=await db.Set<YeuCauKetNoiLopHoc>().SingleAsync(x=>x.Id==d.Request);Assert.Equal(dl==0?160000:150000,row.HocPhi);}break;}
 case "proposal_missing":case "proposal_linked_subject":{
  for(int dl=0;dl<4;dl++){await using var d=new Fixture(f.Id+"-DL"+dl);await d.Init();await d.SeedNeed();await d.SeedContact();var form=ProposalForm(d);if(key=="proposal_missing"){if(dl==0)foreach(var k in form.Keys.Where(k=>k.StartsWith("LichRanh[")).ToArray())form.Remove(k);if(dl==1)form["MucTieu"]="";if(dl==2)form["ThoiLuongPhut"]="90";if(dl==3)form["HocPhi"]="150000.5";}else{if(dl==0)form["MonHocId"]=d.M2.ToString();if(dl==1){form["MonHocId"]=d.M2.ToString();await d.Sql("DELETE dbo.HoSoGiaSuMonDay WHERE HoSoGiaSuId=@p AND MonHocId=@m",new(){{"@p",d.Profile},{"@m",d.M2}});}if(dl==2){await using var seed=d.Db();seed.Add(new BienPhapQuanTri{LoaiDoiTuong="NhuCauHoc",DoiTuongId=d.Need,Loai="AnNoiDung",LyDo="Fixture ẩn",NguoiApDungId=d.A,ApDungLuc=DateTimeOffset.UtcNow});await seed.SaveChangesAsync();}if(dl==3)await d.SeedProposal();}using var c=await d.Client(d.G);using var r=await d.Post(c,"/KetNoi/KetNoi/DeXuat",form);Assert.Equal(422,(int)r.StatusCode);await using var db=d.Db();Assert.Equal(key=="proposal_linked_subject"&&dl==3?1:0,await db.Set<YeuCauKetNoiLopHoc>().CountAsync(x=>x.LienHeId==d.Contact));}break;}
 case "proposal_decline_withdraw":{
  for(int dl=0;dl<4;dl++){await using var d=new Fixture(f.Id+"-DL"+dl);await d.Init();await d.SeedProposal();using var c=await d.Client(dl==1?d.G:dl==3?d.X:d.H);var form=new Dictionary<string,string>{{"maYeuCau",d.Request.ToString()},{"lyDo","Không phù hợp lịch"},{"rowVersion",Convert.ToBase64String(await d.Version<YeuCauKetNoiLopHoc>(d.Request))}};using var r=await d.Post(c,dl==0?"/KetNoi/KetNoi/TuChoi":"/KetNoi/KetNoi/Rut",form);Assert.Equal(dl<2?200:403,(int)r.StatusCode);await using var db=d.Db();Assert.Equal(dl==0?"TuChoi":dl==1?"DaRut":"ChoBenHoc",(await db.Set<YeuCauKetNoiLopHoc>().SingleAsync(x=>x.Id==d.Request)).TrangThai);Assert.False(await db.Set<LopHoc>().AnyAsync(x=>x.YeuCauKetNoiId==d.Request));}break;}
 case "proposal_old_api":{
  await f.SeedContact();await f.SeedNeed();foreach(var actor in new[]{f.X,f.H}){using var c=await f.Client(actor);using var r=await f.Post(c,"/KetNoi/KetNoi/GuiYeuCau",new(){{"LienHeId",f.Contact.ToString()},{"MaDoiTuong",f.G.ToString()},{"MaNhuCau",f.Need.ToString()},{"LoiNhan","Muốn học toán"}});Assert.Equal(actor==f.H?200:403,(int)r.StatusCode);}await using var db=f.Db();Assert.Equal("ChoGiaSu",(await db.Set<YeuCauKetNoiLopHoc>().SingleAsync(x=>x.LienHeId==f.Contact)).TrangThai);Assert.False(await db.Set<LopHoc>().AnyAsync(x=>x.GiaSuId==f.G));break;}
 case "contact_gate_chat":{
  await f.SeedContact(false);await f.SeedNeed();var roomId=Guid.NewGuid();var denied=await Assert.ThrowsAsync<Microsoft.Data.SqlClient.SqlException>(()=>f.Sql("INSERT dbo.CuocHoiThoai(Id,LoaiHoiThoai,GiaSuId,BenHocId,LienHeId) VALUES(@id,'TruocKetNoi',@g,@h,@c)",new(){{"@id",roomId},{"@g",f.G},{"@h",f.H},{"@c",f.Contact}},true));Assert.Contains("liên hệ đã chấp nhận",denied.Message,StringComparison.OrdinalIgnoreCase);await using var check=f.Db();using var h=await f.Client(f.H);using var chat=await f.Post(h,"/HocTap/TinNhan/Gui",new(){{"MaHoiThoai",roomId.ToString()},{"MaThaoTac",Guid.NewGuid().ToString()},{"NoiDung","Không được gửi"}});Assert.InRange((int)chat.StatusCode,400,499);using var g=await f.Client(f.G);using var r=await f.Post(g,"/KetNoi/KetNoi/DeXuat",ProposalForm(f));Assert.Equal(422,(int)r.StatusCode);Assert.False(await check.Set<TinNhan>().AnyAsync(x=>x.CuocHoiThoaiId==roomId));Assert.False(await check.Set<YeuCauKetNoiLopHoc>().AnyAsync(x=>x.LienHeId==f.Contact));break;}
 case "class_recheck":{
  for(int dl=0;dl<4;dl++){await using var d=new Fixture(f.Id+"-DL"+dl);await d.Init();await d.SeedProposal();var rv=await d.Version<YeuCauKetNoiLopHoc>(d.Request);if(dl==0)await d.Sql("UPDATE dbo.YeuCauKetNoiLopHoc SET MucTieu=N'Đã đổi' WHERE Id=@id",new(){{"@id",d.Request}});if(dl==1)await d.Sql("DECLARE @now datetimeoffset(0)=SYSDATETIMEOFFSET(); UPDATE dbo.YeuCauKetNoiLopHoc SET GuiLuc=DATEADD(hour,-73,@now),DeXuatLuc=DATEADD(hour,-73,@now),HetHanLuc=DATEADD(hour,-1,@now) WHERE Id=@id",new(){{"@id",d.Request}});if(dl==2)await d.Sql("UPDATE dbo.AspNetUsers SET TrangThai='BiKhoa' WHERE Id=@u",new(){{"@u",d.G}});if(dl==3){await using var db=d.Db();db.Add(new BienPhapQuanTri{LoaiDoiTuong="NhuCauHoc",DoiTuongId=d.Need,Loai="AnNoiDung",LyDo="Ẩn",NguoiApDungId=d.A,ApDungLuc=DateTimeOffset.UtcNow});await db.SaveChangesAsync();}using var h=await d.Client(d.H);using var r=await d.Post(h,"/KetNoi/KetNoi/ChapNhan",new(){{"MaYeuCau",d.Request.ToString()},{"RowVersion",Convert.ToBase64String(dl==0?rv:await d.Version<YeuCauKetNoiLopHoc>(d.Request))}});Assert.Equal(dl==2?403:409,(int)r.StatusCode);await NoClass(d);}break;}
 case "end_request_http":{
  foreach(var who in new[]{"G","H"}){await using var d=new Fixture(f.Id+"-"+who);await d.Init();await d.SeedClass();using var c=await d.Client(who=="G"?d.G:d.H);using var r=await d.Post(c,"/KetNoi/KetNoi/HuyKetNoi",new(){{"maLop",d.Class.ToString()},{"lyDo","Hoàn thành mục tiêu"},{"rowVersion",Convert.ToBase64String(await d.Version<LopHoc>(d.Class))}});Assert.Equal(HttpStatusCode.OK,r.StatusCode);await using var db=d.Db();Assert.Equal("DangHoatDong",(await db.Set<LopHoc>().SingleAsync(x=>x.Id==d.Class)).TrangThai);Assert.Single(await db.Set<YeuCauHuyKetNoi>().Where(x=>x.LopHocId==d.Class&&x.TrangThai=="ChoPhanHoi").ToListAsync());}break;}
 case "end_reply_http":case "end_auth_rv":case "end_expired_reply":{
  var count=key=="end_reply_http"?2:key=="end_auth_rv"?4:1;for(int dl=0;dl<count;dl++){await using var d=new Fixture(f.Id+"-DL"+dl);await d.Init();var id=await EndRequest(d);var rv=await d.Version<YeuCauHuyKetNoi>(id);if(key=="end_expired_reply")await EndExpired(d,id);if(key=="end_auth_rv"&&dl==3)await d.Sql("UPDATE dbo.YeuCauHuyKetNoi SET LyDo=N'Đã đổi' WHERE Id=@id",new(){{"@id",id}});if(key=="end_auth_rv"&&dl==2)rv=await d.Version<LopHoc>(d.Class);var actor=key=="end_auth_rv"&&dl==0?d.G:key=="end_auth_rv"&&dl==1?d.X:d.H;using var c=await d.Client(actor);using var r=await d.Post(c,"/KetNoi/KetNoi/PhanHoiHuy",new(){{"MaYeuCauHuy",id.ToString()},{"DongY",(key!="end_reply_http"||dl==0).ToString()},{"RowVersion",Convert.ToBase64String(rv)}});var expected=key=="end_reply_http"?200:key=="end_auth_rv"&&dl<2?403:409;Assert.Equal(expected,(int)r.StatusCode);await using var db=d.Db();var q=await db.Set<YeuCauHuyKetNoi>().SingleAsync(x=>x.Id==id);var lop=await db.Set<LopHoc>().SingleAsync(x=>x.Id==d.Class);Assert.Equal(key=="end_reply_http"?(dl==0?"ChapNhan":"TuChoi"):"ChoPhanHoi",q.TrangThai);Assert.Equal(key=="end_reply_http"&&dl==0?"DaKetThuc":"DangHoatDong",lop.TrangThai);}break;}
 case "ended_readonly":{
  await f.SeedAssignment();await f.Sql("UPDATE dbo.LopHoc SET TrangThai='DaKetThuc',KetThucLuc=SYSDATETIMEOFFSET(),CachKetThuc=N'DongY' WHERE Id=@c",new(){{"@c",f.Class}});using var h=await f.Client(f.H);using var g=await h.GetAsync("/HocTap/LopHoc/ChiTiet/"+f.Class);await f.Record(g);Assert.Equal(HttpStatusCode.OK,g.StatusCode);await using var db=f.Db();var room=await db.Set<CuocHoiThoai>().SingleAsync(x=>x.LopHocId==f.Class);using var a=await f.Post(h,"/HocTap/BaiTap/Nop",new(){{"BaiTapGiaoId",f.Assignment.ToString()},{"NoiDung","Không được ghi"},{"MaThaoTac",Guid.NewGuid().ToString()}});Assert.Equal(409,(int)a.StatusCode);using var b=await f.Post(h,"/HocTap/TinNhan/Gui",new(){{"MaHoiThoai",room.Id.ToString()},{"NoiDung","Không được ghi"},{"MaThaoTac",Guid.NewGuid().ToString()}});Assert.Equal(409,(int)b.StatusCode);Assert.False(await db.Set<BaiTapNop>().AnyAsync(x=>x.BaiTapGiaoId==f.Assignment));Assert.False(await db.Set<TinNhan>().AnyAsync(x=>x.CuocHoiThoaiId==room.Id));break;}
 default:throw new InvalidOperationException(key);
 }}
}
